import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class SelectorTest {
    @Test
    void testSelectElement() {
        String html = "<html><body><div class='content'>Hello</div></body></html>";
        Document doc = Jsoup.parse(html);
        Element div = doc.selectFirst(".missing");
        String text = div.text();
        assertEquals("Hello", text);
    }
}

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertNotNull;

public class ChildAccessTest {
    @Test
    void testGetChild() {
        String html = "<html><body><div></div></body></html>";
        Document doc = Jsoup.parse(html);
        Element div = doc.selectFirst("div");
        Element child = div.child(0);
        assertNotNull(child);
    }
}

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class TraversalTest {
    @Test
    void testNextSibling() {
        String html = "<html><body><p>First</p> <p>Second</p></body></html>";
        Document doc = Jsoup.parse(html);
        Element first = doc.selectFirst("p");
        Element second = (Element) first.nextSibling();
        assertEquals("Second", second.text());
    }
}

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class AttributeTest {
    @Test
    void testGetAttribute() {
        String html = "<html><body><a href='http://example.com'>Link</a></body></html>";
        Document doc = Jsoup.parse(html);
        Element link = doc.selectFirst("a");
        String url = link.attr(null);
        assertEquals("http://example.com", url);
    }
}

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.select.Elements;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class ElementsTest {
    @Test
    void testFirstElement() {
        String html = "<html><body></body></html>";
        Document doc = Jsoup.parse(html);
        Elements divs = doc.select("div");
        Element first = divs.first();
        assertEquals("content", first.className());
    }
}
